    @Test
    void validacaoFormaPagamentoInvalida() {
        Item item = new Item("Item", new BigDecimal("10.00"), 1, new BigDecimal("0.10"));

        CheckoutRequest request = new CheckoutRequest(
            Arrays.asList(item),
